import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest

def extract_layout_elements(document_content: bytes, content_type: str = "application/pdf"):
    """
    Extracts layout elements (pages, paragraphs, lines, words, tables) from a document.

    Args:
        document_content (bytes): The content of the document (e.g., PDF, JPEG, PNG).
        content_type (str): The MIME type of the document content (e.g., "application/pdf", "image/jpeg").

    Returns:
        dict: A dictionary containing extracted layout information.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("Please set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    # Use the "prebuilt-layout" model for comprehensive layout extraction
    # This model extracts pages, lines, words, selection marks, tables, and paragraphs.
    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-layout", AnalyzeDocumentRequest(bytes_data=document_content, content_type=content_type)
    )
    result = poller.result()

    extracted_data = {
        "pages": [],
        "paragraphs": [],  # Can be considered 'blocks'
        "tables": [],
        "lines": [],
        "words": []
    }

    if result.pages:
        for page in result.pages:
            page_info = {
                "page_number": page.page_number,
                "width": page.width,
                "height": page.height,
                "unit": page.unit,
            }
            extracted_data["pages"].append(page_info)

            # Extract lines and words per page
            if page.lines:
                for line in page.lines:
                    extracted_data["lines"].append({
                        "content": line.content,
                        "bounding_regions": [r.bounding_box for r in line.bounding_regions] if line.bounding_regions else [],
                        "page_number": page.page_number
                    })
            if page.words:
                for word in page.words:
                    extracted_data["words"].append({
                        "content": word.content,
                        "confidence": word.confidence,
                        "bounding_regions": [r.bounding_box for r in word.bounding_regions] if word.bounding_regions else [],
                        "page_number": page.page_number
                    })

    if result.paragraphs:
        for paragraph in result.paragraphs:
            extracted_data["paragraphs"].append({
                "role": paragraph.role,
                "content": paragraph.content,
                "bounding_regions": [r.bounding_box for r in paragraph.bounding_regions] if paragraph.bounding_regions else [],
                "page_number": paragraph.bounding_regions[0].page_number if paragraph.bounding_regions else None
            })

    if result.tables:
        for table in result.tables:
            table_info = {
                "row_count": table.row_count,
                "column_count": table.column_count,
                "cells": [],
                "bounding_regions": [r.bounding_box for r in table.bounding_regions] if table.bounding_regions else [],
                "page_number": table.bounding_regions[0].page_number if table.bounding_regions else None
            }
            for cell in table.cells:
                table_info["cells"].append({
                    "content": cell.content,
                    "row_index": cell.row_index,
                    "column_index": cell.column_index,
                    "row_span": cell.row_span,
                    "column_span": cell.column_span,
                    "kind": cell.kind,
                    "bounding_regions": [r.bounding_box for r in cell.bounding_regions] if cell.bounding_regions else []
                })
            extracted_data["tables"].append(table_info)

    return extracted_data
